import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        long MOD = 1000000007L;

        if (k == 0) {
            System.out.println(modPow(p, p - 1, MOD));
        } else if (k == 1) {
            System.out.println(modPow(p, p, MOD));
        } else {
            int cycleLength = 1;
            long powerValue = k;
            while (powerValue != 1) {
                cycleLength += 1;
                powerValue = (powerValue * k) % p;
            }
            long numComponents = (p - 1) / cycleLength;
            System.out.println(modPow(p, numComponents, MOD));
        }
        scanner.close();
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
